 for(const sourcePath of ['Copyright','libxslt/xslt.c','libxslt/xsltconfig.h.in']){const url='https://raw.githubusercontent.com/'+row.repo+'/'+row.commit+'/'+sourcePath,response=await fetch(url,{signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error('Fetch '+response.status+': '+url);const b=Buffer.from(await response.arrayBuffer());if(!b.length||b.length>1e6||b.includes(0)||!Buffer.from(b.toString('utf8')).equals(b))throw Error('Invalid original text');const file='libxslt/'+sourcePath;fs.mkdirSync(path.dirname(output+'/'+file),{recursive:true});fs.writeFileSync(output+'/'+file,b,{flag:'wx'});(sourcePath==='Copyright'?row.files:row.identityFiles).push({path:file,sourcePath,url,bytes:b.length,sha256:sha(b)});save();}
